namespace sv_aa02fdea44564369950278d6d11723ff.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@page "/chat"
@using sv_aa02fdea44564369950278d6d11723ff.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@rendermode InteractiveServer

<PageTitle>Team Chat</PageTitle>

<div class="chat-container">
    @* Left Sidebar - Channel List *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h3>Channels</h3>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-description">@TruncateDescription(channel.Description)</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* Main Message Area *@
    <main class="message-area @(_threadOpen ? "thread-open" : "")">
        @if (_activeChannel is not null)
        {
            <div class="message-header">
                <h2># @_activeChannel.Name</h2>
                <p>@_activeChannel.Description</p>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageListScrollAsync">
                @if (_loadingMore)
                {
                    <div class="loading-indicator">Loading older messages...</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var message in _messages)
                    {
                        <div class="message-item" @onmouseenter="() => _hoveredMessageId = message.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-meta">
                                <span class="message-author">@message.Author</span>
                                <span class="message-time">@FormatRelativeTime(message.SentAt)</span>
                            </div>
                            <div class="message-content">@message.Content</div>

                            @if (message.Reactions.Count > 0)
                            {
                                <div class="message-reactions">
                                    @foreach (var reaction in message.Reactions)
                                    {
                                        <span class="reaction-badge" @onclick="() => AddReactionAsync(message.Id, reaction.Emoji)">
                                            @reaction.Emoji @reaction.Users.Count
                                        </span>
                                    }
                                </div>
                            }

                            @if (GetReplyCount(message.Id) > 0)
                            {
                                <a class="thread-link" @onclick="() => OpenThreadAsync(message)">
                                    @GetReplyCount(message.Id) replies
                                </a>
                            }

                            @if (_hoveredMessageId == message.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" @onclick="() => OpenThreadAsync(message)" title="Reply in thread">
                                        💬 Reply
                                    </button>
                                    <div class="react-btn-container">
                                        <button class="action-btn" @onclick="() => ToggleEmojiPicker(message.Id)" title="Add reaction">
                                            😀 React
                                        </button>
                                        @if (_emojiPickerMessageId == message.Id)
                                        {
                                            <div class="emoji-picker">
                                                @foreach (var emoji in _commonEmojis)
                                                {
                                                    <button class="emoji-option" @onclick="() => AddReactionAsync(message.Id, emoji)">
                                                        @emoji
                                                    </button>
                                                }
                                            </div>
                                        }
                                    </div>
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="_newMessageContent" @bind:event="oninput"
                          placeholder="Type a message..." rows="2"
                          @onkeydown="OnMessageKeyDownAsync"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessageContent)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </main>

    @* Right Panel - Thread View *@
    @if (_threadOpen && _threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-btn" @onclick="CloseThread">✕</button>
            </div>
            <div class="thread-root-message">
                <div class="message-meta">
                    <span class="message-author">@_threadRootMessage.Author</span>
                    <span class="message-time">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
                </div>
                <div class="message-content">@_threadRootMessage.Content</div>
            </div>
            <div class="thread-replies">
                @if (_threadMessages is not null)
                {
                    @foreach (var reply in _threadMessages)
                    {
                        <div class="message-item">
                            <div class="message-meta">
                                <span class="message-author">@reply.Author</span>
                                <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="message-content">@reply.Content</div>
                            @if (reply.Reactions.Count > 0)
                            {
                                <div class="message-reactions">
                                    @foreach (var reaction in reply.Reactions)
                                    {
                                        <span class="reaction-badge">@reaction.Emoji @reaction.Users.Count</span>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>
            <div class="thread-input-area">
                <textarea @bind="_threadReplyContent" @bind:event="oninput"
                          placeholder="Reply in thread..." rows="2"
                          @onkeydown="OnThreadKeyDownAsync"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync" disabled="@string.IsNullOrWhiteSpace(_threadReplyContent)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Web;
using sv_aa02fdea44564369950278d6d11723ff.Services;

namespace sv_aa02fdea44564369950278d6d11723ff.Components.Pages;

public partial class Chat
{
    private List<Channel>? _channels;
    private int? _activeChannelId;
    private Channel? _activeChannel;
    private List<Message>? _messages;
    private bool _loadingMore;
    private int _messageSkip;
    private const int PageSize = 30;

    private string _newMessageContent = string.Empty;
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message>? _threadMessages;
    private string _threadReplyContent = string.Empty;

    private ElementReference _messageListRef;

    // Track reply counts from messages that are replies
    private Dictionary<int, int> _replyCounts = new();

    private readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🚀", "👀"];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        _activeChannelId = channel.Id;
        _activeChannel = channel;
        _messageSkip = 0;
        _messages = null;
        _replyCounts.Clear();
        _emojiPickerMessageId = null;

        var messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = messages;
        _messageSkip = messages.Count;
        BuildReplyCounts();

        await ChatService.MarkChannelReadAsync(channel.Id);

        // Update the channel's unread count locally
        var idx = _channels!.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
        {
            _channels[idx] = channel with { UnreadCount = 0 };
            _activeChannel = _channels[idx];
        }
    }

    private async Task OnMessageListScrollAsync()
    {
        // JS interop would be needed for actual scroll position detection.
        // This is a simplified trigger — in production, use JS to detect scroll-to-top.
        // For now we provide the method signature; actual scroll detection requires JS.
    }

    public async Task LoadOlderMessagesAsync()
    {
        if (_loadingMore || _activeChannelId is null) return;

        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messageSkip, PageSize);
        if (older.Count > 0)
        {
            _messages = [..older, ..(_messages ?? [])];
            _messageSkip += older.Count;
            BuildReplyCounts();
        }

        _loadingMore = false;
        StateHasChanged();
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageContent) || _activeChannelId is null) return;

        var sent = await ChatService.SendMessageAsync(_activeChannelId.Value, _newMessageContent.Trim(), null);
        _messages ??= [];
        _messages.Add(sent);
        _newMessageContent = string.Empty;
    }

    private async Task OnMessageKeyDownAsync(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessageAsync();
        }
    }

    private async Task OpenThreadAsync(Message rootMessage)
    {
        _threadRootMessage = rootMessage;
        _threadOpen = true;
        _threadReplyContent = string.Empty;
        _emojiPickerMessageId = null;

        _threadMessages = await ChatService.GetThreadAsync(rootMessage.Id);
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = null;
        _threadReplyContent = string.Empty;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyContent) || _threadRootMessage is null || _activeChannelId is null)
            return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, _threadReplyContent.Trim(), _threadRootMessage.Id);
        _threadMessages ??= [];
        _threadMessages.Add(reply);
        _threadReplyContent = string.Empty;

        // Update reply count
        if (_replyCounts.ContainsKey(_threadRootMessage.Id))
            _replyCounts[_threadRootMessage.Id]++;
        else
            _replyCounts[_threadRootMessage.Id] = 1;
    }

    private async Task OnThreadKeyDownAsync(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Optimistically update the UI
        var message = _messages?.FirstOrDefault(m => m.Id == messageId);
        if (message is not null)
        {
            var existing = message.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                message.Reactions.Add(new Reaction(emoji, ["You"]));
            }
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private void BuildReplyCounts()
    {
        _replyCounts.Clear();
        if (_messages is null) return;

        foreach (var msg in _messages)
        {
            if (msg.ReplyToId is not null)
            {
                _replyCounts.TryGetValue(msg.ReplyToId.Value, out var count);
                _replyCounts[msg.ReplyToId.Value] = count + 1;
            }
        }
    }

    private int GetReplyCount(int messageId)
    {
        return _replyCounts.GetValueOrDefault(messageId, 0);
    }

    private static string TruncateDescription(string description)
    {
        return description.Length <= 40 ? description : string.Concat(description.AsSpan(0, 37), "...");
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;

        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

